function propKey(defs, baseName) {
  if (!defs) return baseName;
  const hit = Object.keys(defs).find((k) => k === baseName || k.startsWith(baseName + "#"));
  return hit || baseName;
}

const rowDefs = rowMain.componentPropertyDefinitions;

const createdNodeIds = [];

